import java.util.List;

public class Stats {
    public static double average(List<Integer> xs) {
        int sum = 0;
        for (int x : xs) sum += x;
        return sum / xs.size();
    }

    public static String first(List<String> names) {
        return names.get(0).trim();
    }
}

